versions.variantCss:
.wemd-series-nav[data-variant="bytedance-series-nav"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  padding: 20px 24px;
  margin: 24px 0;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
}
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-header {
  display: flex;
  align-items: center;
  margin: 0 0 12px 0;
}
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-name {
  color: var(--wemd-text-strong);
  font-size: 16px;
  font-weight: 700;
  margin: 0 8px 0 0;
}
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-desc {
  color: var(--wemd-text-soft);
  font-size: 12px;
  margin: 0;
}
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-progress-bar {
  height: 3px;
  background: var(--wemd-bg-muted);
  border-radius: 2px;
  margin: 0 0 12px 0;
  border-top: 3px solid var(--wemd-primary);
}
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-nav {
  display: flex;
  justify-content: space-between;
  margin: 0 0 12px 0;
}
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-prev,
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-next {
  color: var(--wemd-primary);
  font-size: 13px;
  font-weight: 700;
  margin: 0;
}
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-articles {
  margin: 0;
}
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-item {
  color: var(--wemd-text-normal);
  font-size: 14px;
  padding: 6px 0;
  border-bottom: 1px solid var(--wemd-border-soft);
}
.wemd-series-nav[data-variant="bytedance-series-nav"] .wemd-sn-item-idx {
  display: inline-block;
  color: var(--wemd-primary);
  font-weight: 700;
  margin-right: 8px;
}
